import java.util.Arrays;
import java.util.Comparator;
import java.util.List;
import java.util.ArrayList;

interface SortingAlgorithm<T> {
    void sort(T[] arr);
}

class BubbleSort<T> implements SortingAlgorithm<T> {
    private final Comparator<T> comparator;
    private final boolean trackMetrics;
    private long comparisons;
    private long swaps;

    private BubbleSort(Builder<T> builder) {
        this.comparator = builder.comparator;
        this.trackMetrics = builder.trackMetrics;
    }

    @Override
    public void sort(T[] arr) {
        validateInput(arr);
        for (int i = 0; i < arr.length - 1; i++) {
            if (!performPass(arr, i)) break;
        }
    }

    public void sort(List<T> list) {
        if (list == null || list.size() < 2) return;
        for (int i = 0; i < list.size() - 1; i++) {
            if (!performPassOnList(list, i)) break;
        }
    }

    private boolean performPass(T[] arr, int passIndex) {
        boolean swapped = false;
        for (int j = 0; j < arr.length - passIndex - 1; j++) {
            recordComparison();
            if (comparator.compare(arr[j], arr[j + 1]) > 0) {
                swap(arr, j, j + 1);
                swapped = true;
            }
        }
        return swapped;
    }

    private boolean performPassOnList(List<T> list, int passIndex) {
        boolean swapped = false;
        for (int j = 0; j < list.size() - passIndex - 1; j++) {
            recordComparison();
            if (comparator.compare(list.get(j), list.get(j + 1)) > 0) {
                swapList(list, j, j + 1);
                swapped = true;
            }
        }
        return swapped;
    }

    private void swap(T[] arr, int i, int j) {
        T temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
        recordSwap();
    }

    private void swapList(List<T> list, int i, int j) {
        T temp = list.get(i);
        list.set(i, list.get(j));
        list.set(j, temp);
        recordSwap();
    }

    private void recordComparison() {
        if (trackMetrics) comparisons++;
    }

    private void recordSwap() {
        if (trackMetrics) swaps++;
    }

    private void validateInput(T[] arr) {
        if (arr == null) throw new IllegalArgumentException("Array cannot be null");
    }

    public SortStatistics getStatistics() {
        return new SortStatistics(comparisons, swaps);
    }

    public void resetStatistics() {
        comparisons = 0;
        swaps = 0;
    }

    static class Builder<T> {
        private Comparator<T> comparator = Comparator.naturalOrder();
        private boolean trackMetrics = true;

        public Builder<T> withComparator(Comparator<T> comparator) {
            this.comparator = comparator;
            return this;
        }

        public Builder<T> trackMetrics(boolean track) {
            this.trackMetrics = track;
            return this;
        }

        public BubbleSort<T> build() {
            return new BubbleSort<>(this);
        }
    }

    static class SortStatistics {
        final long comparisons;
        final long swaps;

        SortStatistics(long comparisons, long swaps) {
            this.comparisons = comparisons;
            this.swaps = swaps;
        }

        @Override
        public String toString() {
            return String.format("Comparisons: %d, Swaps: %d", comparisons, swaps);
        }
    }

    public static void main(String[] args) {
        BubbleSort<Integer> sorter = new Builder<Integer>().trackMetrics(true).build();

        Integer[] data = {64, 34, 25, 12, 22, 11, 90};
        sorter.sort(data);
        System.out.println("Sorted array: " + Arrays.toString(data));
        System.out.println("Statistics: " + sorter.getStatistics());

        List<String> strings = new ArrayList<>(Arrays.asList("zebra", "apple", "mango", "banana"));
        sorter.resetStatistics();
        sorter.sort(strings);
        System.out.println("Sorted strings: " + strings);
        System.out.println("Statistics: " + sorter.getStatistics());
    }
}

